import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { useAuth } from '../context/AuthContext';

const DEPTS = [
  { value: 'ai_data', label: 'AI 데이터분석' },
  { value: 'ai_office', label: 'AI 사무' },
  { value: '3d_precision', label: '3D 정밀' },
  { value: 'fire', label: '소방' },
  { value: 'dev_special', label: '발달특화' },
];
const MBTIS = ['INTJ','INTP','ENTJ','ENTP','INFJ','INFP','ENFJ','ENFP','ISTJ','ISTP','ESTJ','ESTP','ISFJ','ISFP','ESFJ','ESFP'];

export default function Register() {
  const { register } = useAuth();
  const navigate = useNavigate();
  const [form, setForm] = useState({ name:'', gender:'남', dept:'ai_data', mbti:'ENFP', intro:'', id:'', password:'', password2:'', phone:'' });
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const submit = () => {
    if (!form.name || !form.id || !form.password || !form.phone) { setError('필수 항목을 모두 입력해주세요.'); return; }
    if (form.password !== form.password2) { setError('비밀번호가 일치하지 않습니다.'); return; }
    if (form.password.length < 4) { setError('비밀번호는 4자 이상이어야 합니다.'); return; }
    const result = register({ name: form.name, gender: form.gender, dept: form.dept, mbti: form.mbti, intro: form.intro, id: form.id, password: form.password, phone: form.phone });
    if (!result.ok) { setError(result.msg); return; }
    setDone(true);
    setTimeout(() => navigate('/login'), 2000);
  };

  return (
    <>
      <Navbar />
      <div style={{ maxWidth: 520, margin: '40px auto', padding: '0 20px 60px' }}>
        <div className="card">
          <h2 style={{ fontSize: 24, fontWeight: 700, marginBottom: 4 }}>회원가입</h2>
          <p style={{ color: 'var(--muted)', fontSize: 14, marginBottom: 28 }}>경기남부직능원 친구 찾기 서비스에 가입하세요</p>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <div className="form-group">
              <label>이름 *</label>
              <input placeholder="홍길동" value={form.name} onChange={e => set('name', e.target.value)} />
            </div>
            <div className="form-group">
              <label>성별 *</label>
              <select value={form.gender} onChange={e => set('gender', e.target.value)}>
                <option value="남">남</option>
                <option value="여">여</option>
              </select>
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <div className="form-group">
              <label>해당 직군 *</label>
              <select value={form.dept} onChange={e => set('dept', e.target.value)}>
                {DEPTS.map(d => <option key={d.value} value={d.value}>{d.label}</option>)}
              </select>
            </div>
            <div className="form-group">
              <label>MBTI *</label>
              <select value={form.mbti} onChange={e => set('mbti', e.target.value)}>
                {MBTIS.map(m => <option key={m} value={m}>{m}</option>)}
              </select>
            </div>
          </div>

          <div className="form-group">
            <label>자기소개</label>
            <textarea placeholder="간단하게 자신을 소개해주세요 😊" value={form.intro} onChange={e => set('intro', e.target.value)} />
          </div>

          <div className="form-group">
            <label>아이디 *</label>
            <input placeholder="영문/숫자 조합" value={form.id} onChange={e => set('id', e.target.value)} />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 16px' }}>
            <div className="form-group">
              <label>비밀번호 *</label>
              <input type="password" placeholder="4자 이상" value={form.password} onChange={e => set('password', e.target.value)} />
            </div>
            <div className="form-group">
              <label>비밀번호 확인 *</label>
              <input type="password" placeholder="다시 입력" value={form.password2} onChange={e => set('password2', e.target.value)} />
            </div>
          </div>

          <div className="form-group">
            <label>휴대폰 번호 *</label>
            <input placeholder="010-0000-0000" value={form.phone} onChange={e => set('phone', e.target.value)} />
          </div>

          {error && <div className="error-msg" style={{ marginBottom: 12 }}>{error}</div>}
          {done && <div className="success-msg">🎉 회원가입 완료! 로그인 페이지로 이동합니다...</div>}

          {!done && <button className="btn-primary" onClick={submit}>가입하기</button>}

          <p style={{ textAlign: 'center', marginTop: 20, fontSize: 14, color: 'var(--muted)' }}>
            이미 계정이 있으신가요?{' '}
            <span style={{ color: 'var(--primary)', fontWeight: 600, cursor: 'pointer' }} onClick={() => navigate('/login')}>로그인</span>
          </p>
        </div>
      </div>
    </>
  );
}
